namespace fs=std::filesystem;
struct Declaration {std::string file,kind,name,statement; int line=0; std::set<std::string> features;};
static std::string csv(const std::string& s){std::string r="\"";for(char c:s){if(c=='\"')r+='\"';r+=c;}return r+'\"';}
static std::string lower(std::string s){for(char& c:s)c=static_cast<char>(std::tolower(static_cast<unsigned char>(c)));return s;}
static bool word(const std::string& s,const std::string& w){const size_t p=s.find(w);if(p==std::string::npos)return false;const size_t e=p+w.size();auto id=[](char c){return std::isalnum(static_cast<unsigned char>(c))!=0||c=='_';};return (p==0||!id(s[p-1]))&&(e==s.size()||!id(s[e]));}
static std::set<std::string> features(const std::string& s){std::set<std::string> f; const std::string l=lower(s);for(const std::string t:{"Nat","Int","Fin","ZMod","Bool","List","Array","Vector","Real","Rat","Complex","Matrix","Set"})if(word(s,t))f.insert("type:"+t);if(s.find('+')!=std::string::npos)f.insert("op:add");if(s.find('*')!=std::string::npos)f.insert("op:mul");if(s.find('^')!=std::string::npos)f.insert("op:pow");if(s.find('%')!=std::string::npos||l.find("mod")!=std::string::npos)f.insert("op:mod");if(s.find("=")!=std::string::npos)f.insert("relation:eq");if(s.find("≤")!=std::string::npos||s.find("<=")!=std::string::npos)f.insert("relation:le");if(s.find("∧")!=std::string::npos)f.insert("logic:and");if(s.find("→")!=std::string::npos)f.insert("logic:implies");return f;}
static std::string join(const std::set<std::string>& x){std::string r;for(const auto& s:x){if(!r.empty())r+=';';r+=s;}return r;}
static void check(int r,sqlite3* db,const std::string& m){if(r!=SQLITE_OK)throw std::runtime_error(m+": "+(db?sqlite3_errmsg(db):"no database handle"));}
static std::vector<Declaration> load(const fs::path& src,int limit,const std::string& filter){if(!fs::is_regular_file(src))throw std::runtime_error("Source DB missing: "+src.string());sqlite3* db=nullptr;const int rc=sqlite3_open_v2(src.string().c_str(),&db,SQLITE_OPEN_READONLY,nullptr);if(rc!=SQLITE_OK){const std::string msg=db?sqlite3_errmsg(db):"unknown";if(db)sqlite3_close(db);throw std::runtime_error("read-only open: "+msg);}try{check(sqlite3_exec(db,"PRAGMA query_only=ON",nullptr,nullptr,nullptr),db,"read-only pragma");sqlite3_stmt* st=nullptr;const std::string sql="SELECT file,line,kind,name,statement FROM declarations WHERE statement IS NOT NULL AND length(statement)>0 AND (?1='' OR file LIKE ?2) ORDER BY file,line LIMIT ?3";check(sqlite3_prepare_v2(db,sql.c_str(),-1,&st,nullptr),db,"read declarations");sqlite3_bind_text(st,1,filter.c_str(),-1,SQLITE_TRANSIENT);const std::string like="%"+filter+"%";sqlite3_bind_text(st,2,like.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int(st,3,limit);std::vector<Declaration> out;int step=SQLITE_ROW;auto col=[&](int i){const unsigned char* v=sqlite3_column_text(st,i);return v?std::string(reinterpret_cast<const char*>(v)):std::string();};while((step=sqlite3_step(st))==SQLITE_ROW){Declaration d;d.file=col(0);d.line=sqlite3_column_int(st,1);d.kind=col(2);d.name=col(3);d.statement=col(4);d.features=features(d.statement);out.push_back(std::move(d));}sqlite3_finalize(st);if(step!=SQLITE_DONE)throw std::runtime_error("SQLite cursor failed");sqlite3_close(db);return out;}catch(...){sqlite3_close(db);throw;}}
static std::string family(const std::set<std::string>& f){if(f.count("op:mod")&&f.count("op:add"))return "modular_accumulator";if(f.count("op:mul")&&f.count("op:add"))return "multiply_accumulate";if(f.count("op:pow"))return "power_transform";if(f.count("op:add"))return "additive_transform";if(f.count("op:mul"))return "multiplicative_transform";return "structural_relation";}
static void generate(const fs::path& dir,const std::string& fam){fs::create_directories(dir);std::string expr="(state + input) % 65521u";if(fam=="multiply_accumulate")expr="(state * 17u + input) % 65521u";else if(fam=="modular_accumulator")expr="(state + input * 3u) % 65521u";else if(fam=="power_transform")expr="(state * state + input) % 65521u";else if(fam=="multiplicative_transform")expr="(state * (input + 1u)) % 65521u";std::ofstream h(dir/"candidate.hpp");h<<"#pragma once\n#include <cstdint>\nnamespace discovery_candidate {\ninline std::uint32_t step(std::uint32_t state,std::uint32_t input) noexcept {return "<<expr<<";}\n}\n";std::ofstream main(dir/"main.cpp");main<<"#include \"candidate.hpp\"\n#include <cstdint>\n#include <fstream>\n#include <iostream>\n#include <string>\nint main(int argc,char** argv){if(argc==2 && std::string(argv[1])==\"--selftest\"){std::uint32_t state=0;for(std::uint32_t i=0;i<256u;++i)state=discovery_candidate::step(state,i);std::cout<<\"SELFTEST PASS state=\"<<state<<'\\n';return 0;}if(argc!=2){std::cerr<<\"usage: discovered_app output.csv\\n\";return 2;}std::ofstream out(argv[1]);if(!out)return 3;out<<\"index,input,state\\n\";std::uint32_t state=0;for(std::uint32_t i=0;i<256u;++i){state=discovery_candidate::step(state,i);out<<i<<','<<i<<','<<state<<'\\n';}return out?0:4;}\n";std::ofstream cm(dir/"CMakeLists.txt");cm<<"cmake_minimum_required(VERSION 3.21)\nproject(DiscoveredSemanticCandidate LANGUAGES CXX)\nadd_executable(discovered_app main.cpp)\ntarget_compile_features(discovered_app PRIVATE cxx_std_20)\nif(MSVC)\n target_compile_options(discovered_app PRIVATE /W4 /WX /permissive- /EHsc)\nelse()\n target_compile_options(discovered_app PRIVATE -Wall -Wextra -Wpedantic -Werror)\nendif()\n";}
static int run(const fs::path& src,const fs::path& dst,int limit,const std::string& filter){auto ds=load(src,limit,filter);fs::create_directories(dst);std::ofstream d(dst/"declarations.csv");d<<"file,line,kind,name,features,statement\n";std::map<std::string,std::vector<size_t>> byFamily;for(size_t i=0;i<ds.size();++i){const auto& v=ds[i];d<<csv(v.file)<<','<<v.line<<','<<csv(v.kind)<<','<<csv(v.name)<<','<<csv(join(v.features))<<','<<csv(v.statement)<<'\n';byFamily[family(v.features)].push_back(i);}std::ofstream edges(dst/"relations.csv");edges<<"source_name,target_name,shared_features,evidence,proof_status\n";size_t relations=0;for(size_t i=0;i<ds.size();++i){for(size_t j=i+1;j<ds.size()&&j<i+65;++j){std::set<std::string> both;std::set_intersection(ds[i].features.begin(),ds[i].features.end(),ds[j].features.begin(),ds[j].features.end(),std::inserter(both,both.end()));if(both.size()<2)continue;edges<<csv(ds[i].name)<<','<<csv(ds[j].name)<<','<<csv(join(both))<<','<<csv(ds[i].file+":"+std::to_string(ds[i].line)+" | "+ds[j].file+":"+std::to_string(ds[j].line))<<",HEURISTIC_ONLY\n";++relations;}}std::ofstream hypotheses(dst/"hypotheses.csv");hypotheses<<"family,declarations,evidence,translated_semantics,application_hypothesis\n";int apps=0;for(const auto& kv:byFamily){if(kv.first=="structural_relation"||kv.second.empty())continue;const auto& example=ds[kv.second[0]];hypotheses<<csv(kv.first)<<','<<kv.second.size()<<','<<csv(example.file+":"+std::to_string(example.line)+" "+example.name)<<",NOT_TRANSLATED,"<<csv("Experiment with " +kv.first+" recurrence on streams")<<'\n';generate(dst/"applications"/("application_"+std::to_string(++apps)),kv.first);}std::ofstream report(dst/"RESEARCH_REPORT.md");report<<"# MathResearchEngine v9 – Semantic Mathematical Discovery\n\nSource opened with SQLITE_OPEN_READONLY; no source modifications.\n\n- Declarations sampled: "<<ds.size()<<"\n- Heuristic feature-overlap relationships: "<<relations<<"\n- Experimental application families: "<<apps<<"\n- Source filter: "<<filter<<"\n\n## Scientific scope\n\nFeatures are extracted from the original Lean declaration text (type names and mathematical symbols). Relationships are **lexical/type-token hypotheses only**. No Lean elaboration, formal type unification, proof, or semantics-preserving Lean-to-C++ translation has been performed. Generated kernels are independent experimental designs inspired by observed symbol families, not equivalent implementations of the source declarations.\n";if(!d||!edges||!hypotheses||!report)throw std::runtime_error("Report write failed");std::cout<<"SEMANTIC_V9_PASS declarations="<<ds.size()<<" relations="<<relations<<" applications="<<apps<<" mode=READ_ONLY proof=NOT_CLAIMED output="<<dst.string()<<'\n';return 0;}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="selftest"){const auto f=features("theorem x (a b : Nat) : a + b = b + a");if(!f.count("type:Nat")||!f.count("op:add")||!f.count("relation:eq"))return 1;std::cout<<"SEMANTIC_V9_SELFTEST PASS\n";return 0;}if(argc<3||argc>5){std::cerr<<"usage: math_semantic_discovery source.sqlite output-dir [limit=1000] [file-filter]\n";return 2;}const int limit=argc>=4?std::stoi(argv[3]):1000;if(limit<1||limit>100000)throw std::runtime_error("limit must be 1..100000");return run(argv[1],argv[2],limit,argc==5?argv[4]:"");}catch(const std::exception& e){std::cerr<<"SEMANTIC_V9_ERROR: "<<e.what()<<'\n';return 1;}}
